using UnityEngine;
using UnityEngine.Rendering;

/// Holds references to the material/profile assets generated by the editor setup script.
/// Everything else (track, car, camera, lights, audio) is built at runtime by RaceManager.
public class GameAssets : MonoBehaviour
{
    [Header("Track")]
    public Material gridFloor;
    public Material gridWall;
    public Material dark;
    public Material hazard;
    public Material warning;
    public Material checkpoint;
    public Material finish;
    public Material strip;
    public Material[] gearMats = new Material[4];

    [Header("Car")]
    public Material carBody;
    public Material carGlass;
    public Material carWheel;
    public Material carAccent;
    public Material headlight;
    public Material trail;

    [Header("Post")]
    public VolumeProfile postProfile;

    public static readonly Color[] GearColors =
    {
        new Color(0.10f, 0.90f, 1.00f), // 1 GRIP      - cyan
        new Color(1.00f, 0.20f, 0.85f), // 2 FLIP      - magenta
        new Color(0.55f, 1.00f, 0.25f), // 3 SLOW-MO   - lime
        new Color(1.00f, 0.45f, 0.10f), // 4 OVERDRIVE - orange
    };

    public static Color GearColor(int gear) => GearColors[Mathf.Clamp(gear, 1, 4) - 1];
}
